DROP TABLE IF EXISTS `mermas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `mermas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `lote_id` int(11) NOT NULL,
  `producto_id` int(11) NOT NULL,
  `cantidad` int(11) NOT NULL,
  `causal` varchar(30) NOT NULL,
  `observacion` varchar(255) DEFAULT NULL,
  `precio_unitario` decimal(10,2) NOT NULL,
  `estado` varchar(20) NOT NULL DEFAULT 'PENDIENTE',
  `solicitado_por` int(11) NOT NULL,
  `solicitado_en` timestamp NOT NULL DEFAULT current_timestamp(),
  `autorizado_por` int(11) DEFAULT NULL,
  `autorizado_en` datetime DEFAULT NULL,
  `motivo_rechazo` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `producto_id` (`producto_id`),
  KEY `solicitado_por` (`solicitado_por`),
  KEY `autorizado_por` (`autorizado_por`),
  KEY `idx_mermas_lote` (`lote_id`,`estado`),
  CONSTRAINT `mermas_ibfk_1` FOREIGN KEY (`lote_id`) REFERENCES `lotes` (`id`),
  CONSTRAINT `mermas_ibfk_2` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`),
  CONSTRAINT `mermas_ibfk_3` FOREIGN KEY (`solicitado_por`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `mermas_ibfk_4` FOREIGN KEY (`autorizado_por`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
